properties.query:
let baselineWindow = 24h;
let alertWindow = 15m;
let gateMultiplier = 2.5;
let floorBytes = 10000000.0;
let WhitelistedGCS = _GetWatchlist('C2_Whitelisted_GCS_List') | project GCS_IP;
let dynGate = toscalar(
    UAVSatcomLink_CL
    | where TimeGenerated > ago(baselineWindow)
    | summarize percentile(PayloadBytes, 99) * gateMultiplier
);
let byteGate = max_of(dynGate, floorBytes);
UAVSatcomLink_CL
| where TimeGenerated > ago(alertWindow)
| where DstAddr !in (WhitelistedGCS)
| where PayloadBytes > byteGate
| extend TriggerReason = strcat("C2은닉유출_SATCOM채널위장_", tostring(toint(PayloadBytes/1000000)), "MB_Dst_", DstAddr)
| extend Severity = "High"
| project TimeGenerated, UAVId, LinkId, SessionId, SrcAddr, DstAddr, Mode, Encoding, PayloadBytes, TriggerReason, Severity
| order by TimeGenerated desc
